const retrieved = load("loci_availability_retrieve_v1")?.structuredContent;
const anchor = retrieved?.items?.find(item => item.role === "anchor" && item.extent?.file === "entry.ts");
const expected = retrieved?.sources?.find(source => source.file === "entry.ts" && source.source_ref === anchor?.source_ref);
if (!anchor || !expected || typeof anchor.source_ref !== "string") {
  text({stage: "loci_read", execution: "shape_error", error: "No entry.ts anchor and matching source in the retrieve result.", recovery_key: "loci_availability_retrieve_v1"});
} else {
  const key = "loci_availability_read_v1";
  try {
    const result = await tools.mcp__loci__loci_read({
      repo: "/private/tmp/loci-r1-availability-ujjoju0f/availability-eager/workspace",
      source_ref: anchor.source_ref
    });
    store(key, result);
    const data = result?.structuredContent;
    if (result?.isError || !data || typeof data !== "object" || data.error) {
      text({stage: "loci_read", execution: "error", recovery_key: key, result: data ?? result});
    } else if (data.status !== "ok" || data.schema_version !== 1 || typeof data.complete !== "boolean" || !data.source || typeof data.source.content !== "string") {
      text({stage: "loci_read", execution: "shape_error", recovery_key: key, result: data});
    } else {
      const source = data.source;
      const fields = ["file", "start_byte", "end_byte", "start_line", "end_line", "content_hash", "content", "source_ref"];
      const mismatches = fields.filter(field => source[field] !== expected[field]);
      text({
        stage: "loci_read",
        execution: mismatches.length ? "comparison_failed" : "success",
        fixture_check: {against: "entry.ts source returned by loci_retrieve for the fixture repository", matched_fields: fields.filter(field => !mismatches.includes(field)), mismatches},
        recovery_key: key,
        result: data
      });
    }
  } catch (error) {
    text({stage: "loci_read", execution: "error", error: String(error)});
  }
}
